VALUES (68612, 'tt0417550', NULL, 'Confession', 'Confession', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/8GsUHI7cGKhpCkepB0hvE4Amv5Z.jpg', 'https://image.tmdb.org/t/p/original/200PSWTTtBK9rS2PPYdNsUMwa2v.jpg', 'In a small Catholic boarding school an unspeakable act has been committed. When High School student, Luther Scott, confesses to Father Michael Kelly, Kelly is bound silent to the particulars of a grisly murder. Now, framed guilty by the desperate teen, Kelly must decide to keep his silence or throw away everything the priesthood holds sacred.', NULL, NULL, 2.1289, 4.7, 0, 9.51, '2026-10-18 22:36:17', '2026-10-18 22:36:17')
