VALUES (375262, 'tt5083738', NULL, 'The Favourite', 'The Favourite', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/cwBq0onfmeilU5xgqNNjJAMPfpw.jpg', 'https://image.tmdb.org/t/p/original/iSskYDN193CJfTbSpFfscSwZ9Sx.jpg', 'England, early 18th century. The close relationship between Queen Anne and Sarah Churchill is threatened by the arrival of Sarah''s cousin, Abigail Hill, resulting in a bitter rivalry between the two cousins to be the Queen''s favourite.', NULL, NULL, 11.1419, 7.483, 0, 1.92035714285714291e+01, '2026-07-15 12:01:52', '2026-10-18 22:36:17')
