VALUES (11527, 'tt0082348', NULL, 'Excalibur', 'Excalibur', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/cTWF6zkr5mUOnheowKODIijWYcN.jpg', 'https://image.tmdb.org/t/p/original/mrabn7LREC8HOBBUyQIXZsQvWk3.jpg', 'Arthur fulfills his fate by bringing together the Knights of the Round Table at Camelot and unifying the country. However, this flawed monarch faces greater tests ahead in pursuit of love, the Holy Grail, and his nation''s survival.', NULL, NULL, 5.3152, 7.0, 0, 1.01823505154639178e+02, '2026-07-15 12:01:52', '2026-10-18 22:36:17')
