VALUES (3558, 'tt0172493', NULL, 'Girl, Interrupted', 'Girl, Interrupted', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/dOBdatHIVppvmRFw2z7bf9VKJr9.jpg', 'https://image.tmdb.org/t/p/original/jDePFWhpfkY4GJm41qiRffJ0NGq.jpg', 'Set in the changing world of the late 1960s, Susanna Kaysen''s prescribed "short rest" from a psychiatrist she had met only once becomes a strange, unknown journey into Alice''s Wonderland, where she struggles with the thin line between normal and crazy. Susanna soon realizes how hard it is to get out once she has been committed, and she ultimately has to choose between the world of people who belong inside or the difficult world of reality outside.', NULL, NULL, 7.5231, 7.6, 0, 5.98118181818181824e+01, '2026-07-15 12:01:52', '2026-10-18 22:36:17')
