VALUES (16391, 'tt0039192', NULL, 'Black Narcissus', 'Black Narcissus', 'movie', 1947, 'https://image.tmdb.org/t/p/w500/jSbFWWbkUq5N5ikewJHNATcWnxS.jpg', 'https://image.tmdb.org/t/p/original/hAyWibhJjMHyWXrMVX8N2MrEqF8.jpg', 'A group of Anglican nuns, led by Sister Clodagh, are sent to a mountain in the Himalayas. The climate in the region is hostile and the nuns are housed in an odd old palace. They work to establish a school and a hospital, but slowly their focus shifts. Sister Ruth falls for a government worker, Mr. Dean, and begins to question her vow of celibacy. As Sister Ruth obsesses over Mr. Dean, Sister Clodagh becomes immersed in her own memories of love.', NULL, NULL, 1.978, 7.509, 0, 2.74031818181818174e+01, '2026-07-15 12:01:52', '2026-10-18 22:36:17')
