VALUES (10223, 'tt0120324', NULL, 'A Simple Plan', 'A Simple Plan', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/wO2gH7DMqpMeHlj5QmDhW4IkgAr.jpg', 'https://image.tmdb.org/t/p/original/gtdCmYpubVkkvTQ8rdR9tkixDSj.jpg', 'Captivated by the lure of sudden wealth, the quiet rural lives of two brothers erupt into conflicts of greed, paranoia and distrust when over $4 million in cash is discovered at the remote site of a downed small airplane. Their simple plan to retain the money while avoiding detection opens a Pandora''s box when the fear of getting caught triggers panicked behavior and leads to virulent consequences.', NULL, NULL, 3.9366, 7.216, 0, 2.61771428571428543e+01, '2026-07-20 01:02:04', '2026-10-18 22:36:17')
