VALUES (2277, 'tt0182789', NULL, 'Bicentennial Man', 'Bicentennial Man', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/wrs23eO0VEWwOQpXoOasMnlW9Y4.jpg', 'https://image.tmdb.org/t/p/original/aIVL5crQCBMPxKMoExiIsUDFPeR.jpg', 'Richard Martin buys a gift, a new NDR-114 robot. The product is named Andrew by the youngest of the family''s children. "Bicentennial Man" follows the life and times of Andrew, a robot purchased as a household appliance programmed to perform menial tasks. As Andrew begins to experience emotions and creative thought, the Martin family soon discovers they don''t have an ordinary robot.', NULL, NULL, 8.7842, 7.27, 0, 8.43333333333333357e+00, '2026-08-11 22:09:33', '2026-10-18 22:36:17')
