VALUES (30698, 'tt0400435', NULL, 'The Five People You Meet In Heaven', 'The Five People You Meet In Heaven', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/1fvMz3gy4YuqPDC5LotTWofFFcx.jpg', 'https://image.tmdb.org/t/p/original/llZz64BIZcIyGnazveysBCFsPsN.jpg', 'On his 83rd birthday, Eddie, a war vet and a maintenance worker at the Ruby Pier amusement park, dies while trying to save a girl who is sitting under a falling ride. When he awakens in the afterlife, he encounters five people with ties to his corporeal existence who help him understand the meaning of his life.', NULL, NULL, 2.2139, 6.968, 0, 6.77, '2026-08-21 01:43:43', '2026-10-18 22:36:17')
