VALUES (13435, 'tt0168786', NULL, 'Antwone Fisher', 'Antwone Fisher', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/j9lCK1aFXqMO3hzhGiqCNU8coIX.jpg', 'https://image.tmdb.org/t/p/original/83xzg9g16CulQbYISZRF64EoeSY.jpg', 'A sailor prone to violent outbursts is sent to a naval psychiatrist for help. Refusing at first to open up, the young man eventually breaks down and reveals a horrific childhood. Through the guidance of his doctor, he confronts his painful past and begins a quest to find the family he never knew.', NULL, NULL, 4.4015, 6.95, 0, 11.26, '2026-08-24 01:47:08', '2026-10-18 22:36:17')
